style.css:
body {
  background-color: transparent !important;
}

html::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  height: 100%;
  width: 100%;
  background-image: url("https://i.imgur.com/UbziJpi.jpeg");
  background-size: cover;
  background-position: center;
  background-attachment: fixed;
  background-repeat: no-repeat;
  z-index: -1;
  pointer-events: none;
}
